INSERT INTO "discovery_content" ("id","kind","slug","title","category","summary","body","relatedDishes","sourceUrl","sourceName","published","publishedAt","updatedAt") VALUES
('tradition-avurudu','tradition','avurudu-food-traditions','Avurudu: food and new beginnings','Sinhala and Tamil New Year','Explore the role of milk rice and traditional sweets in Sri Lanka’s New Year celebrations.','Food is central to the April New Year celebrations. In many households, preparing milk rice and arranging sweets such as kavum and kokis mark the occasion. Sharing festive meals and visiting family help carry traditions across generations. Customs differ among communities, regions and households.',ARRAY['kiribath']::TEXT[],'https://www.destinationsrilanka.travel/festivals/','Destination Sri Lanka — Festivals',TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('tradition-thai-pongal','tradition','thai-pongal-harvest-traditions','Thai Pongal: a harvest of gratitude','Tamil harvest traditions','Learn how the preparation of Pongal rice connects food, agriculture and gratitude.','Thai Pongal is a harvest celebration observed by Tamil communities, including in Sri Lanka. Preparing rice with milk and allowing the pot to overflow is a symbolic expression of abundance. The celebration honours the harvest and the role of agriculture; customs vary by community and household. This guide describes the tradition rather than announcing an event.',ARRAY[]::TEXT[],'https://www.mfa.gov.lk/en/news/celebration-thai-pongal-sri-lanka-deputy-high-commission-chennai','Sri Lanka Ministry of Foreign Affairs — Thai Pongal',TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
